words_for.example:
#include <cinux/bit_ops/bitmap.hpp>

using namespace cinux::base::bit;

void Example() {
    constexpr auto kWords = Bitmap::words_for(100);  // kWords = 2 · 100 位要两个 64 位字
    static_assert(kWords == 2);
    static_assert(Bitmap::words_for(64) == 1);  // 恰好一个字
}

extract.example:
#include <cinux/bit_ops/bitmask.hpp>

using namespace cinux::base::bit;

void Example() {
    constexpr BitMask<unsigned> kStatus{0xABCD1234u};

    constexpr auto kField = kStatus.extract(BitRange{.low = 8, .width = 8});
    // kField = 0x12 · 第 15..8 位，右对齐取出
    static_assert(kField == 0x12u);
}

LowByte.example:
#include <cinux/bit_ops/bit_ops.hpp>

using namespace cinux::base::bit;

void Example() {
    constexpr auto kLow = LowByte(0xABCDu);  // kLow = 0xCD · 205，只留最低 8 位
    static_assert(kLow == 0xCDu);
}
